set local lock_timeout='5s';
set local statement_timeout='60s';
-- Reviewed release delta; previously tested in staging.
create schema atlas_account_private;
revoke all on schema atlas_account_private from public, anon, authenticated;
create table atlas_account_private.operations (
  operation_id uuid primary key,
  user_id uuid not null references auth.users(id) on delete cascade deferrable initially deferred,
  actor_id uuid not null references auth.users(id),
  revision bigint not null,
  created_at timestamptz not null default now()
);
revoke all on atlas_account_private.operations from public,anon,authenticated;
create function atlas_account_private.prepare_assignment() returns trigger
language plpgsql security definer set search_path='' as $fn$
declare
  request jsonb; previous_revision bigint := 0; expected_revision bigint;
  home_code text; target_role text; login_name text; display_name text;
  actor uuid; operation uuid; allowed_codes text[]; known_roles text[];
begin
  request := new.raw_app_meta_data->'atlas_assignment_request';
  if tg_op='UPDATE' then
    previous_revision := coalesce((old.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0);
  end if;
  if request is null or request='null'::jsonb then
    if tg_op='UPDATE' and previous_revision>0 and new.deleted_at is null and
      (new.raw_app_meta_data - array['provider','providers']) is distinct from
      (old.raw_app_meta_data - array['provider','providers']) then
      -- Unrelated metadata may change; authorization fields may not bypass this protocol.
      if row(new.raw_app_meta_data->'role',new.raw_app_meta_data->'atlas_role',
          new.raw_app_meta_data->'roles',new.raw_app_meta_data->'warehouse_code',
          new.raw_app_meta_data->'home_warehouse_code',new.raw_app_meta_data->'warehouse_access',
          new.raw_app_meta_data->'atlas_assignment_revision')
        is distinct from row(old.raw_app_meta_data->'role',old.raw_app_meta_data->'atlas_role',
          old.raw_app_meta_data->'roles',old.raw_app_meta_data->'warehouse_code',
          old.raw_app_meta_data->'home_warehouse_code',old.raw_app_meta_data->'warehouse_access',
          old.raw_app_meta_data->'atlas_assignment_revision') then
        raise exception 'ASSIGNMENT_PROTOCOL_REQUIRED' using errcode='23514';
      end if;
    end if;
    return new;
  end if;
  if jsonb_typeof(request)<>'object' then raise exception 'ASSIGNMENT_REQUEST_INVALID' using errcode='23514'; end if;
  actor := (request->>'actor_id')::uuid;
  operation := (request->>'operation_id')::uuid;
  if actor is null or operation is null then raise exception 'ASSIGNMENT_ACTOR_OPERATION_REQUIRED' using errcode='23514'; end if;
  if not exists(select 1 from auth.users u join public.profiles p on p.user_id=u.id
    where u.id=actor and u.deleted_at is null and p.role='admin'
      and (u.banned_until is null or u.banned_until<=now())
      and (u.raw_app_meta_data->>'role' in ('admin','administrator')
        or u.raw_app_meta_data->>'atlas_role' in ('admin','administrator'))) then
    raise exception 'ADMINISTRATOR_REQUIRED' using errcode='42501';
  end if;
  expected_revision := (request->>'expected_revision')::bigint;
  if expected_revision is null or expected_revision<>previous_revision then
    raise exception 'ASSIGNMENT_REVISION_CONFLICT' using errcode='40001';
  end if;
  home_code := upper(trim(request->>'warehouse_code'));
  target_role := lower(trim(request->>'role'));
  login_name := request->>'login_name';
  display_name := trim(request->>'display_name');
  if target_role is null or target_role not in ('picker','supervisor','office_receiver','admin') then
    raise exception 'ATLAS_ROLE_INVALID' using errcode='23514'; end if;
  if login_name is null or login_name !~ '^[a-z0-9._-]{2,48}$' or lower(new.email) is distinct from login_name||'@users.atlas.invalid' then
    raise exception 'LOGIN_NAME_INVALID' using errcode='23514'; end if;
  if display_name is null or length(display_name) not between 1 and 60 then
    raise exception 'DISPLAY_NAME_REQUIRED' using errcode='23514'; end if;
  lock table public.warehouses in share mode;
  if home_code is null or not exists(select 1 from public.warehouses where code=home_code and active) then
    raise exception 'WAREHOUSE_REQUIRED_OR_INVALID' using errcode='23514'; end if;
  select array_agg(code order by code) into allowed_codes from public.warehouses
    where active and (target_role='admin' or code=home_code);
  insert into atlas_account_private.operations(operation_id,user_id,actor_id,revision)
    values(operation,new.id,actor,previous_revision+1);
  new.raw_app_meta_data := (coalesce(new.raw_app_meta_data,'{}')-'atlas_assignment_request')
    || jsonb_build_object('role',target_role,'atlas_role',target_role,'login_name',login_name,
      'warehouse_code',home_code,'home_warehouse_code',home_code,
      'warehouse_access',to_jsonb(allowed_codes),'atlas_assignment_revision',previous_revision+1,
      'atlas_assignment_operation_id',operation,'atlas_assignment_actor_id',actor);
  if new.raw_app_meta_data ? 'roles' then
    select coalesce(array_agg(value),'{}') into known_roles from jsonb_array_elements_text(new.raw_app_meta_data->'roles')
      where lower(value) not in ('picker','supervisor','office','office_receiver','admin','administrator');
    new.raw_app_meta_data := new.raw_app_meta_data || jsonb_build_object('roles',to_jsonb(known_roles||array[target_role]));
  end if;
  new.raw_user_meta_data := coalesce(new.raw_user_meta_data,'{}') || jsonb_build_object('display_name',display_name);
  return new;
end $fn$;
create function atlas_account_private.apply_assignment() returns trigger
language plpgsql security definer set search_path='' as $fn$
declare home_id uuid; revision bigint; profile_role public.app_role;
begin
  revision:=coalesce((new.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0);
  if revision=0 then return new; end if;
  if tg_op='UPDATE' and revision=coalesce((old.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0) then return new; end if;
  select id into strict home_id from public.warehouses where code=new.raw_app_meta_data->>'home_warehouse_code' and active;
  profile_role := (case when new.raw_app_meta_data->>'role'='office_receiver' then 'picker' else new.raw_app_meta_data->>'role' end)::public.app_role;
  insert into public.profiles(user_id,display_name,role,warehouse_id)
    values(new.id,new.raw_user_meta_data->>'display_name',profile_role,home_id)
    on conflict(user_id) do update set display_name=excluded.display_name,role=excluded.role,warehouse_id=excluded.warehouse_id;
  delete from public.profile_warehouse_access where user_id=new.id;
  insert into public.profile_warehouse_access(user_id,warehouse_id,granted_by_user_id)
    select new.id,w.id,(new.raw_app_meta_data->>'atlas_assignment_actor_id')::uuid
    from public.warehouses w where w.active and w.code in
      (select jsonb_array_elements_text(new.raw_app_meta_data->'warehouse_access'));
  return new;
end $fn$;
revoke all on function atlas_account_private.prepare_assignment() from public,anon,authenticated;
revoke all on function atlas_account_private.apply_assignment() from public,anon,authenticated;
create trigger atlas_prepare_assignment before insert or update on auth.users
  for each row execute function atlas_account_private.prepare_assignment();
create trigger zz_atlas_apply_assignment after insert or update on auth.users
  for each row execute function atlas_account_private.apply_assignment();

-- A restrictive policy ANDs with the existing permissive policies. Staging-only
-- product choice: warehouse inventory requires an authenticated warehouse grant.
-- Preserve public inventory SELECT; restrict only warehouse writes.
create policy atlas_warehouse_insert on public.locations as restrictive for insert to authenticated
  with check (public.atlas_user_can_access_warehouse(warehouse_id));
create policy atlas_warehouse_update on public.locations as restrictive for update to authenticated
  using (public.atlas_user_can_access_warehouse(warehouse_id))
  with check (public.atlas_user_can_access_warehouse(warehouse_id));
create policy atlas_warehouse_delete on public.locations as restrictive for delete to authenticated
  using (public.atlas_user_can_access_warehouse(warehouse_id));
create policy atlas_warehouse_boundary on public.inventory_activity as restrictive for all to authenticated
  using (public.atlas_user_can_access_warehouse(warehouse_id))
  with check (public.atlas_user_can_access_warehouse(warehouse_id));
create policy atlas_warehouse_boundary on public.location_history as restrictive for all to authenticated
  using (public.atlas_user_can_access_warehouse(warehouse_id))
  with check (public.atlas_user_can_access_warehouse(warehouse_id));
-- TRUNCATE bypasses row policies; application roles must never receive it.
revoke truncate,trigger,references on public.warehouses,public.profile_warehouse_access from anon,authenticated;

create or replace function public.audit_location_change() returns trigger
language plpgsql security definer set search_path='' as $fn$
begin
  if tg_op='INSERT' then
    insert into public.location_history(location_id,sku_id,action,old_record,new_record,changed_by,warehouse_id)
      values(new.id,new.sku_id,'INSERT',null,to_jsonb(new),auth.uid(),new.warehouse_id);
    return new;
  elsif tg_op='UPDATE' then
    insert into public.location_history(location_id,sku_id,action,old_record,new_record,changed_by,warehouse_id)
      values(new.id,new.sku_id,'UPDATE',to_jsonb(old),to_jsonb(new),auth.uid(),new.warehouse_id);
    return new;
  else
    insert into public.location_history(location_id,sku_id,action,old_record,new_record,changed_by,warehouse_id)
      values(old.id,old.sku_id,'DELETE',to_jsonb(old),null,auth.uid(),old.warehouse_id);
    return old;
  end if;
end $fn$;

