-- Capture from the normalized row instead: never store passwords or editable metadata.
create or replace function atlas_account_private.capture_request() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  update atlas_account_private.operations set request=jsonb_build_object(
    'role',new.raw_app_meta_data->>'role',
    'warehouse_code',new.raw_app_meta_data->>'home_warehouse_code',
    'login_name',new.raw_app_meta_data->>'login_name',
    'display_name',new.raw_user_meta_data->>'display_name')
    where operation_id=(new.raw_app_meta_data->>'atlas_assignment_operation_id')::uuid and request is null;
  return new;
end $$;
revoke all on function atlas_account_private.capture_request() from public,anon,authenticated;
create trigger zzz_atlas_capture_assignment after insert or update on auth.users
  for each row execute function atlas_account_private.capture_request();

create function public.atlas_account_admin_snapshot(p_actor uuid, p_operation uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare answer jsonb;
begin
  if p_operation is not null then
    select jsonb_build_object('user_id',o.user_id,'revision',o.revision,'request',o.request)
      into answer from atlas_account_private.operations o join auth.users u on u.id=o.actor_id
      where o.operation_id=p_operation and o.actor_id=p_actor and u.deleted_at is null
        and (u.banned_until is null or u.banned_until<=now());
    return answer;
  end if;
  if not exists(select 1 from auth.users u join public.profiles p on p.user_id=u.id
    where u.id=p_actor and u.deleted_at is null and p.role='admin'
      and (u.banned_until is null or u.banned_until<=now())
      and (u.raw_app_meta_data->>'role' in ('admin','administrator')
        or u.raw_app_meta_data->>'atlas_role' in ('admin','administrator'))) then
    raise exception 'ADMINISTRATOR_REQUIRED' using errcode='42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',u.id,'display_name',coalesce(p.display_name,u.raw_user_meta_data->>'display_name',split_part(u.email,'@',1)),
    'login_name',coalesce(u.raw_app_meta_data->>'login_name',split_part(u.email,'@',1)),
    'role',coalesce(u.raw_app_meta_data->>'atlas_role',u.raw_app_meta_data->>'role',p.role::text,'picker'),
    'warehouse_code',w.code,'warehouse_access',coalesce((select jsonb_agg(wa.code order by wa.code)
      from public.profile_warehouse_access a join public.warehouses wa on wa.id=a.warehouse_id and wa.active where a.user_id=u.id),'[]'::jsonb),
    'assignment_revision',coalesce((u.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0),
    'active',(u.banned_until is null or u.banned_until<=now()),'last_sign_in_at',u.last_sign_in_at,
    'created_at',u.created_at,'is_current',u.id=p_actor) order by u.id),'[]'::jsonb)
    into answer from auth.users u left join public.profiles p on p.user_id=u.id
    left join public.warehouses w on w.id=p.warehouse_id where u.deleted_at is null;
  return answer;
end $$;
revoke all on function public.atlas_account_admin_snapshot(uuid,uuid) from public,anon,authenticated;
grant execute on function public.atlas_account_admin_snapshot(uuid,uuid) to service_role;

create function atlas_account_private.check_consistency() returns trigger
language plpgsql security definer set search_path='' as $$
declare subject uuid; u auth.users; p public.profiles; actual text[]; expected text[];
begin
  if tg_table_schema='auth' then subject:=coalesce(new.id,old.id);
  else subject:=coalesce(new.user_id,old.user_id); end if;
  select * into u from auth.users where id=subject for update;
  if not found or u.deleted_at is not null or coalesce((u.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0)=0 then return null; end if;
  select * into p from public.profiles where user_id=subject;
  if not found or p.role::text is distinct from (case when u.raw_app_meta_data->>'role'='office_receiver' then 'picker' else u.raw_app_meta_data->>'role' end)
    or not exists(select 1 from public.warehouses where id=p.warehouse_id and code=u.raw_app_meta_data->>'home_warehouse_code') then
    raise exception 'ACCOUNT_ASSIGNMENT_INCONSISTENT' using errcode='23514';
  end if;
  select coalesce(array_agg(w.code order by w.code),'{}') into actual
    from public.profile_warehouse_access a join public.warehouses w on w.id=a.warehouse_id where a.user_id=subject;
  select coalesce(array_agg(value order by value),'{}') into expected
    from jsonb_array_elements_text(u.raw_app_meta_data->'warehouse_access');
  if actual is distinct from expected then raise exception 'ACCOUNT_ASSIGNMENT_INCONSISTENT' using errcode='23514'; end if;
  -- An UPDATE moving the ownership key must check the old owner too.
  if tg_table_schema<>'auth' then
    if tg_op='UPDATE' and old.user_id<>new.user_id then
      raise exception 'ACCOUNT_OWNERSHIP_IMMUTABLE' using errcode='23514';
    end if;
  end if;
  return null;
end $$;
revoke all on function atlas_account_private.check_consistency() from public,anon,authenticated;
create constraint trigger atlas_assignment_consistent after insert or update or delete on public.profiles
  deferrable initially deferred for each row execute function atlas_account_private.check_consistency();
create constraint trigger atlas_assignment_consistent after insert or update or delete on public.profile_warehouse_access
  deferrable initially deferred for each row execute function atlas_account_private.check_consistency();
create constraint trigger atlas_assignment_consistent after insert or update on auth.users
  deferrable initially deferred for each row execute function atlas_account_private.check_consistency();

-- Existing tokens must lose inventory access after soft-delete/ban or reassignment.
create or replace function public.atlas_user_can_access_warehouse(p_warehouse_id uuid)
returns boolean language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.profile_warehouse_access a join auth.users u on u.id=a.user_id
    join public.warehouses w on w.id=a.warehouse_id and w.active
    where a.user_id=auth.uid() and a.warehouse_id=p_warehouse_id and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=now()));
$$;
notify pgrst,'reload schema';

