 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare subject uuid; u auth.users; p public.profiles; actual text[]; expected text[];
begin
  if tg_table_schema<>'auth' then
    if tg_op='UPDATE' and old.user_id<>new.user_id then
      raise exception 'ACCOUNT_OWNERSHIP_IMMUTABLE' using errcode='23514';
    end if;
  end if;
  if tg_table_schema='auth' then subject:=coalesce(new.id,old.id);
  else subject:=coalesce(new.user_id,old.user_id); end if;
  select * into u from auth.users where id=subject for no key update;
  if not found or u.deleted_at is not null or coalesce((u.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0)=0 then return null; end if;
  select * into p from public.profiles where user_id=subject;
  if not found or p.role::text is distinct from (case when u.raw_app_meta_data->>'role'='office_receiver' then 'picker' else u.raw_app_meta_data->>'role' end)
    or not exists(select 1 from public.warehouses where id=p.warehouse_id and code=u.raw_app_meta_data->>'home_warehouse_code') then
    raise exception 'ACCOUNT_ASSIGNMENT_INCONSISTENT' using errcode='23514';
  end if;
  select coalesce(array_agg(w.code order by w.code),'{}') into actual
    from public.profile_warehouse_access a join public.warehouses w on w.id=a.warehouse_id where a.user_id=subject;
  select coalesce(array_agg(value order by value),'{}') into expected
    from jsonb_array_elements_text(u.raw_app_meta_data->'warehouse_access');
  if actual is distinct from expected then raise exception 'ACCOUNT_ASSIGNMENT_INCONSISTENT' using errcode='23514'; end if;
  -- An UPDATE moving the ownership key must check the old owner too.

  return null;
end $function$;

-- Reviewed release delta; previously tested in staging.
-- Preserve legacy rows: NULL ownership is intentionally inaccessible to clients.
alter table public.atlas_coc_sessions
  add column owner_user_id uuid references auth.users(id),
  add column warehouse_id uuid references public.warehouses(id);
alter table public.atlas_coc_sessions enable row level security;
revoke all on public.atlas_coc_sessions from public, anon, authenticated;
create index atlas_coc_owned_device_lookup on public.atlas_coc_sessions
  (owner_user_id, warehouse_id, device_id, updated_at desc);

create schema atlas_coc_private;
revoke all on schema atlas_coc_private from public,anon,authenticated;

create function atlas_coc_private.authorize(p_code text) returns uuid
language plpgsql security definer set search_path='' as $$
declare warehouse uuid;
begin
  if auth.uid() is null then raise exception 'ATLAS_AUTH_REQUIRED' using errcode='42501'; end if;
  -- Current server-side access, never client metadata or a stale JWT role.
  select w.id into warehouse from public.warehouses w
    join public.profile_warehouse_access a on a.warehouse_id=w.id
    join auth.users u on u.id=a.user_id
    where w.code=p_code and w.active and u.id=auth.uid()
      and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now());
  if warehouse is null then raise exception 'COC_WAREHOUSE_ACCESS_REQUIRED' using errcode='42501'; end if;
  return warehouse;
end $$;
revoke all on function atlas_coc_private.authorize(text) from public,anon,authenticated;

create function public.atlas_save_owned_coc_snapshot(p_session jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare
  actor uuid := auth.uid();
  warehouse uuid;
  coc_id text := nullif(btrim(p_session->>'id'),'');
  device text := nullif(btrim(p_session->>'deviceId'),'');
  draft_status text := p_session->>'status';
  prior public.atlas_coc_sessions;
begin
  warehouse := atlas_coc_private.authorize(p_session->>'warehouseCode');
  if jsonb_typeof(p_session) is distinct from 'object' or
     p_session->>'ownerUserId' is distinct from actor::text or
     coc_id is null or length(coc_id)>140 or device is null or length(device)>100 or
     draft_status is null or draft_status not in ('active','report') or
     jsonb_typeof(p_session->'pallets') is distinct from 'array' or
     octet_length(p_session::text)>5000000 then
    raise exception 'COC_SNAPSHOT_INVALID' using errcode='22023';
  end if;
  -- Serialize saves and close for this account/device/warehouse, including first insert.
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||warehouse::text||':'||device,0));
  select * into prior from public.atlas_coc_sessions where id=coc_id for update;
  if found and (prior.owner_user_id is distinct from actor or
      prior.warehouse_id is distinct from warehouse or prior.device_id<>device) then
    raise exception 'COC_DRAFT_OWNER_MISMATCH' using errcode='42501';
  end if;
  if prior.status='closed' then raise exception 'COC_DRAFT_CLOSED' using errcode='22023'; end if;
  update public.atlas_coc_sessions set status='closed',closed_at=now(),updated_at=now()
    where owner_user_id=actor and warehouse_id=warehouse and device_id=device
      and id<>coc_id and status in ('active','report');
  insert into public.atlas_coc_sessions
    (id,device_id,status,order_number,employee,state,owner_user_id,warehouse_id)
    values(coc_id,device,draft_status,left(coalesce(p_session->>'invoiceNumber',''),80),
      left(coalesce(p_session->>'employee',''),60),p_session,actor,warehouse)
  on conflict(id) do update set state=excluded.state,status=excluded.status,
    order_number=excluded.order_number,employee=excluded.employee,updated_at=now()
  where atlas_coc_sessions.owner_user_id=actor and atlas_coc_sessions.warehouse_id=warehouse
    and atlas_coc_sessions.device_id=device and atlas_coc_sessions.status<>'closed';
  if not found then raise exception 'COC_DRAFT_OWNER_MISMATCH' using errcode='42501'; end if;
end $$;

create function public.atlas_get_owned_device_coc(p_device_id text,p_warehouse_code text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare warehouse uuid; answer jsonb;
begin
  warehouse := atlas_coc_private.authorize(p_warehouse_code);
  select state into answer from public.atlas_coc_sessions
    where owner_user_id=auth.uid() and warehouse_id=warehouse and device_id=p_device_id
      and status in ('active','report') order by updated_at desc limit 1;
  return answer;
end $$;

create function public.atlas_close_owned_coc_session(p_session_id text,p_device_id text,p_warehouse_code text)
returns void language plpgsql security definer set search_path='' as $$
declare warehouse uuid; actor uuid:=auth.uid();
begin
  warehouse := atlas_coc_private.authorize(p_warehouse_code);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||warehouse::text||':'||p_device_id,0));
  if p_session_id is null or length(p_session_id) not between 1 and 140 or
     p_device_id is null or length(p_device_id) not between 1 and 100 then
    raise exception 'COC_SNAPSHOT_INVALID' using errcode='22023';
  end if;
  -- A close may arrive before the first delayed save. Reserve a closed marker
  -- so that save cannot resurrect a discarded or already-transferred report.
  insert into public.atlas_coc_sessions(id,device_id,status,state,owner_user_id,warehouse_id,closed_at)
    values(p_session_id,p_device_id,'closed','{}'::jsonb,actor,warehouse,now())
    on conflict(id) do nothing;
  update public.atlas_coc_sessions set status='closed',closed_at=now(),updated_at=now()
    where id=p_session_id and device_id=p_device_id and owner_user_id=actor and warehouse_id=warehouse;
end $$;

revoke all on function public.atlas_save_owned_coc_snapshot(jsonb) from public,anon,authenticated;
revoke all on function public.atlas_get_owned_device_coc(text,text) from public,anon,authenticated;
revoke all on function public.atlas_close_owned_coc_session(text,text,text) from public,anon,authenticated;
grant execute on function public.atlas_save_owned_coc_snapshot(jsonb) to authenticated;
grant execute on function public.atlas_get_owned_device_coc(text,text) to authenticated;
grant execute on function public.atlas_close_owned_coc_session(text,text,text) to authenticated;
-- Old clients retain their local draft but cannot use the unowned cloud protocol.
revoke all on function public.atlas_save_coc_snapshot(jsonb) from public,anon,authenticated;
revoke all on function public.atlas_get_device_coc(text) from public,anon,authenticated;
revoke all on function public.atlas_close_coc_session(text,text) from public,anon,authenticated;
notify pgrst,'reload schema';
